def paint_schedule(board, spans):
    if not isinstance(board, list):
        raise TypeError("board must be a list")

    width = None
    for row in board:
        if not isinstance(row, list):
            raise TypeError("each row must be a list")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("board must be rectangular")
        if any(not isinstance(cell, str) for cell in row):
            raise TypeError("cells must be strings")

    try:
        pending = list(spans)
    except TypeError as exc:
        raise TypeError("spans must be iterable") from exc

    checked = []
    height = len(board)
    actual_width = 0 if width is None else width
    for span in pending:
        if not isinstance(span, (list, tuple)):
            raise TypeError("each span must be a sequence")
        if len(span) != 3:
            raise ValueError("each span must contain three values")
        row, start, end = span
        if any(isinstance(value, bool) or not isinstance(value, int)
               for value in (row, start, end)):
            raise TypeError("span coordinates must be integers")
        if start > end:
            raise ValueError("span start must not exceed its end")
        if not (0 <= row < height and 0 <= start <= end < actual_width):
            raise ValueError("span coordinate is out of bounds")
        checked.append((row, start, end))

    result = list(board)
    for row, start, end in checked:
        if start == end:
            result[row][start] = "X"
        else:
            result[row][start] = "<"
            for column in range(start + 1, end):
                result[row][column] = "="
            result[row][end] = ">"
    return result

